<?php
namespace App\Http\Controllers;
use App\Services\DocumentWorkflowService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DocumentRouteController extends Controller{
public function __construct(private DocumentWorkflowService $wf){}
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('edo.manage'),403);}
public function add(Request $r,$id){$this->manage($r);$d=DB::table('official_documents')->find($id);abort_if(!$d||!in_array($d->status,['draft','registered']),409);$x=$r->validate(['action'=>'required|in:approve,visa,sign,review','assignee_user_id'=>'nullable|exists:users,id','assignee_role'=>'nullable|string|max:100','due_on'=>'nullable|date']);abort_if(empty($x['assignee_user_id'])&&empty($x['assignee_role']),422,'Укажите сотрудника или роль');$step=(DB::table('document_routes')->where('official_document_id',$id)->max('step')??0)+1;DB::table('document_routes')->insert($x+['official_document_id'=>$id,'step'=>$step,'status'=>'waiting','created_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'route_step_added','Шаг '.$step.': '.$x['action']);return back();}
public function start(Request $r,$id){$this->manage($r);$d=DB::table('official_documents')->find($id);abort_if(!$d||$d->status!=='registered',409);abort_unless(DB::table('document_routes')->where('official_document_id',$id)->exists(),422,'Маршрут пуст');DB::table('official_documents')->where('id',$id)->update(['status'=>'routing','updated_at'=>now()]);$this->wf->activateNext($id);$this->wf->event($id,$r->user()->id,'routing_started','Маршрут согласования запущен');return back();}
public function act(Request $r,$step){$s=DB::table('document_routes')->find($step);abort_if(!$s||$s->status!=='active',409);abort_unless($this->wf->canAct($r->user(),$s),403);$x=$r->validate(['decision'=>'required|in:approved,rejected','comment'=>'nullable|string|max:5000']);DB::transaction(function()use($s,$x,$r){DB::table('document_routes')->where('id',$s->id)->update(['status'=>$x['decision'],'comment'=>$x['comment']??null,'acted_by'=>$r->user()->id,'acted_at'=>now(),'updated_at'=>now()]);if($x['decision']==='rejected')DB::table('official_documents')->where('id',$s->official_document_id)->update(['status'=>'rejected','updated_at'=>now()]);});$this->wf->event($s->official_document_id,$r->user()->id,'route_'.$x['decision'],'Шаг '.$s->step.($x['comment']?': '.$x['comment']:''));if($x['decision']==='approved')$this->wf->activateNext($s->official_document_id);return back();}
public function sign(Request $r,$id){$d=DB::table('official_documents')->find($id);abort_if(!$d||$d->status!=='approved',409);abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('edo.approve')||$r->user()->canDo('edo.manage'),403);$snap=$this->wf->immutableSnapshot($id);DB::table('official_documents')->where('id',$id)->update(['status'=>'signed','signed_by'=>$r->user()->id,'signed_at'=>now(),'snapshot_json'=>json_encode($snap,JSON_UNESCAPED_UNICODE),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'signed','Подписана версия '.$d->current_version.', зафиксирован снимок');return back();}
public function task(Request $r,$id){$this->manage($r);$x=$r->validate(['assigned_to'=>'required|exists:users,id','instruction'=>'required|string|max:10000','due_on'=>'nullable|date']);DB::table('document_tasks')->insert($x+['official_document_id'=>$id,'status'=>'new','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'task_created','Создано поручение');return back();}
public function taskDone(Request $r,$task){$t=DB::table('document_tasks')->find($task);abort_if(!$t,404);abort_unless($r->user()->isSuperAdmin()||$t->assigned_to==$r->user()->id||$r->user()->canDo('edo.manage'),403);$x=$r->validate(['result'=>'required|string|max:10000']);DB::table('document_tasks')->where('id',$task)->update(['status'=>'done','result'=>$x['result'],'completed_at'=>now(),'updated_at'=>now()]);$this->wf->event($t->official_document_id,$r->user()->id,'task_completed',$x['result']);return back();}
public function acknowledgeAdd(Request $r,$id){$this->manage($r);$x=$r->validate(['user_ids'=>'required|array|min:1','user_ids.*'=>'exists:users,id']);foreach($x['user_ids'] as $uid)DB::table('document_acknowledgements')->insertOrIgnore(['official_document_id'=>$id,'user_id'=>$uid,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function acknowledge(Request $r,$id){$a=DB::table('document_acknowledgements')->where(['official_document_id'=>$id,'user_id'=>$r->user()->id])->first();abort_if(!$a,403);DB::table('document_acknowledgements')->where('id',$a->id)->update(['acknowledged_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'acknowledged','Ознакомлен с документом');return back();}
public function archive(Request $r,$id){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('edo.archive'),403);$d=DB::table('official_documents')->find($id);abort_if(!$d||!in_array($d->status,['signed','closed']),409);DB::table('official_documents')->where('id',$id)->update(['status'=>'archived','closed_by'=>$r->user()->id,'closed_at'=>now(),'updated_at'=>now()]);$this->wf->event($id,$r->user()->id,'archived','Передан в архив');return back();}
}